// Generated from the Windows faces' hdmx tables (Windows 11, 2026-10-23).

/// The widths a face's hinting gives its characters at the sizes it
/// lists, where they are not its advance rounded to the pixel: Arial's W
/// is 83 pixels at 83 an em, its 0.9 em being 78.3. Excel prints with
/// them, each character a whole 600-dpi dot on from the last
/// (FormulaEvalTestData_Copy's "WILL_NEVER_IMPLEMENT" steps 83, 23, 46,
/// as Arial's hdmx at 83). By face (bold and italic named after it), by
/// pixels an em: "code:pixels over the rounded advance", in hex and
/// decimal; the rest are the rounded advance.
enum SheetHinting {
    static func departure(_ face: String, em: Int, _ ch: Character) -> Int {
        guard ch.unicodeScalars.count == 1, let v = ch.unicodeScalars.first?.value,
              let sizes = _parsed[face], let row = sizes[em] else { return 0 }
        return row[v] ?? 0
    }

    static func has(_ face: String) -> Bool { _table[face] != nil }

    private static let _parsed: [String: [Int: [UInt32: Int]]] = _table.mapValues { sizes in
        sizes.mapValues { row in
            var m: [UInt32: Int] = [:]
            for item in row.split(separator: ",") {
                let p = item.split(separator: ":")
                if p.count == 2, let k = UInt32(p[0], radix: 16), let d = Int(p[1]) { m[k] = d }
            }
            return m
        }
    }

